{
  "version": 1,
  "units": "mm",
  "name": "bench rectangular-to-round transition",
  "parameters": {
    "rect_width": {
      "value": 40.0,
      "min": 20,
      "max": 80,
      "label": "Rectangle width (X)",
      "unit": "mm",
      "group": "Body"
    },
    "rect_depth": {
      "value": 30.0,
      "min": 15,
      "max": 60,
      "label": "Rectangle depth (Y)",
      "unit": "mm",
      "group": "Body"
    },
    "circle_radius": {
      "value": 15.0,
      "min": 5,
      "max": 40,
      "label": "Circle radius",
      "unit": "mm",
      "group": "Body"
    },
    "transition_height": {
      "value": 50.0,
      "min": 10,
      "max": 100,
      "label": "Transition height",
      "unit": "mm",
      "group": "Body"
    }
  },
  "operations": [
    {
      "id": "transition",
      "kind": "loft",
      "plane": "xy",
      "correspondence": "rectangle_corners_to_circle_diagonals",
      "profiles": [
        {
          "shape": "rectangle",
          "center": [
            0,
            0,
            0
          ],
          "width": "rect_width",
          "height": "rect_depth"
        },
        {
          "shape": "circle",
          "center": [
            0,
            0,
            "transition_height"
          ],
          "radius": "circle_radius"
        }
      ]
    }
  ],
  "output": "transition"
}

